<?php
define('AJAX_SCRIPT',true);require('../../config.php');$versionid=required_param('versionid',PARAM_INT);$v=$DB->get_record('wslib_version',['id'=>$versionid,'state'=>'draft'],'*',MUST_EXIST);$cfg=get_config('local_digieraoffice');$raw=file_get_contents('php://input');$payload=json_decode($raw,true);if(!is_array($payload)){http_response_code(400);echo json_encode(['error'=>1]);exit;}$auth=$_SERVER['HTTP_AUTHORIZATION']??'';$token='';if(preg_match('/Bearer\s+(.+)/i',$auth,$m))$token=trim($m[1]);if($token==='')$token=(string)($payload['token']??'');try{if($token==='')throw new Exception('Missing JWT');\local_digieraoffice\jwt::decode($token,(string)$cfg->jwtsecret);$status=(int)($payload['status']??0);if(in_array($status,[2,6],true)&&!empty($payload['url'])){$downloadurl=(string)$payload['url'];$configuredhost=strtolower((string)parse_url((string)$cfg->documentserverurl,PHP_URL_HOST));$downloadhost=strtolower((string)parse_url($downloadurl,PHP_URL_HOST));if(strtolower((string)parse_url($downloadurl,PHP_URL_SCHEME))!=='https'||$downloadhost===''||$downloadhost!==$configuredhost)throw new Exception('Rejected callback URL');require_once($CFG->libdir.'/filelib.php');$curl=new curl();$raw=$curl->get($downloadurl,[],['CURLOPT_TIMEOUT'=>120]);$info=$curl->get_info();if((int)($info['http_code']??0)<200||(int)($info['http_code']??0)>=300||!is_string($raw)||$raw==='')throw new Exception('Download failed');$tmp=make_request_directory().'/office.bin';if(file_put_contents($tmp,$raw)===false)throw new Exception('Write failed');$current=\local_worksheetlibrary\service\file_service::primary($versionid);$name=$current?$current->get_filename():($v->filename?:'worksheet.docx');$file=\local_worksheetlibrary\service\file_service::store_path($versionid,$tmp,$name,$v->mimetype);$DB->update_record('wslib_version',(object)['id'=>$versionid,'filename'=>$file->get_filename(),'mimetype'=>$file->get_mimetype(),'contenthash'=>$file->get_contenthash()]);}echo json_encode(['error'=>0]);}catch(Throwable $e){http_response_code(403);echo json_encode(['error'=>1]);}
